import React, { useState, useEffect } from 'react'

/**
 * Payment Confirmation Dialog with Amount Received Input
 */
const PaymentConfirmDialog = ({
  isOpen,
  onClose,
  onConfirm,
  billCount,
  grandTotal,
  creditBalance = 0,
  loading = false,
  totalSurcharge = 0, // Total surcharge amount that can be waived
  autoSelectedAmount = null // Add this prop
}) => {
  const [amountReceived, setAmountReceived] = useState('')
  const [error, setError] = useState('')
  const [waiveSurcharge, setWaiveSurcharge] = useState(false)

  // Helper function to round to 2 decimal places
  const roundTo2 = (num) => Math.round(num * 100) / 100
  
  // Calculate amount with/without surcharge
  const grandTotalWithoutSurcharge = roundTo2(grandTotal - totalSurcharge)
  const effectiveGrandTotal = roundTo2(waiveSurcharge ? grandTotalWithoutSurcharge : grandTotal)
  
  // Calculate credit to apply and amount after credit
  const creditToApply = roundTo2(Math.min(creditBalance, effectiveGrandTotal))
  const amountAfterCredit = roundTo2(effectiveGrandTotal - creditToApply)
  const remainingCredit = roundTo2(creditBalance - creditToApply)

  useEffect(() => {
    if (isOpen) {
      // If autoSelectedAmount is provided (from auto-select feature), use it
      if (autoSelectedAmount !== null && autoSelectedAmount !== undefined) {
        setAmountReceived(parseFloat(autoSelectedAmount).toFixed(2))
      } else {
        // Otherwise pre-fill with amount after credit application
        setAmountReceived(amountAfterCredit.toFixed(2))
      }
      setError('')
    }
  }, [isOpen, amountAfterCredit, autoSelectedAmount])

  const handleConfirm = () => {
    const received = roundTo2(parseFloat(amountReceived))
    
    if (isNaN(received) || received < 0) {
      setError('Please enter a valid amount')
      return
    }
    
    // Amount after credit should match or be less (with tolerance for floating point errors)
    if (received < amountAfterCredit - 0.01) {
      setError(`Amount received (₱${received.toFixed(2)}) is less than required (₱${amountAfterCredit.toFixed(2)})`)
      return
    }
    
    // Calculate new credit (overpayment after credit application)
    const newCredit = roundTo2(received - amountAfterCredit)
    
    // Pass credit to apply (from existing balance), new credit (from overpayment), and waiveSurcharge flag
    onConfirm(received, creditToApply, newCredit, waiveSurcharge)
  }

  if (!isOpen) return null

  const overpayment = roundTo2(parseFloat(amountReceived || 0) - amountAfterCredit)
  const hasOverpayment = overpayment > 0.01

  return (
    <div className={`modal ${isOpen ? 'show' : ''}`} style={{ display: isOpen ? 'block' : 'none', zIndex: 2000 }} tabIndex="-1" role="dialog" aria-modal="true">
      <div className="modal-dialog modal-lg" role="document" style={{ zIndex: 2001 }}>
        <div className="modal-content">
          <div className="modal-header bg-success text-white">
            <h5 className="modal-title">Confirm Payment Processing</h5>
            <button type="button" className="btn-close" aria-label="Close" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            <div className="card border-info mb-3">
              <div className="card-body">
                <div className="d-flex justify-content-between mb-2">
                  <span className="text-muted">Number of Bills:</span>
                  <strong>{billCount}</strong>
                </div>
                <hr className="my-2" />
                <div className="d-flex justify-content-between mb-2">
                  <span className="text-muted">Grand Total:</span>
                  <strong className="text-success">₱{grandTotal.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</strong>
                </div>
                {totalSurcharge > 0 && waiveSurcharge && (
                  <div className="d-flex justify-content-between mb-2">
                    <span className="text-muted">Surcharge Waived:</span>
                    <strong className="text-danger">-₱{totalSurcharge.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</strong>
                  </div>
                )}
                {creditToApply > 0 && (
                  <div className="d-flex justify-content-between mb-2">
                    <span className="text-muted">Credit Applied:</span>
                    <strong className="text-warning">-₱{creditToApply.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</strong>
                  </div>
                )}
                <div className="d-flex justify-content-between align-items-center mt-3 p-3 border border-primary border-dashed">
                  <span className="fw-bold text-muted">Amount to Pay:</span>
                  <span className="h5 fw-bold text-success">₱{amountAfterCredit.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                </div>
              </div>
            </div>

            {totalSurcharge > 0 && (
              <div className="form-check mb-3">
                <input className="form-check-input" type="checkbox" id="waiveSurcharge" checked={waiveSurcharge} onChange={(e) => setWaiveSurcharge(e.target.checked)} disabled={loading} />
                <label className="form-check-label" htmlFor="waiveSurcharge">
                  Waive Surcharge (₱{totalSurcharge.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}) - Remove late payment penalty
                </label>
              </div>
            )}

            <div className="mb-3">
              <label className="form-label">Amount Received</label>
              <div className="input-group">
                <span className="input-group-text">₱</span>
                <input
                  type="number"
                  className={`form-control ${error ? 'is-invalid' : ''}`}
                  value={amountReceived}
                  onChange={(e) => { setAmountReceived(e.target.value); setError(''); }}
                  required
                  disabled={loading}
                  step="0.01"
                  autoFocus
                />
                {error && <div className="invalid-feedback">{error}</div>}
              </div>
            </div>

            {!error && hasOverpayment && (
              <div className="alert alert-success" role="alert">
                <strong>Overpayment Detected</strong>
                <div>New credit: <strong>₱{overpayment.toFixed(2)}</strong> will be saved to customer's account.</div>
              </div>
            )}

            {creditToApply > 0 && (
              <div className="alert alert-info" role="alert">
                <strong>Credit Auto-Applied</strong>
                <div>₱{creditToApply.toFixed(2)} from available balance.{remainingCredit > 0 && ` Remaining: ₱${remainingCredit.toFixed(2)}`}</div>
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose} disabled={loading}>Cancel</button>
            <button type="button" className="btn btn-success" onClick={handleConfirm} disabled={loading}>{loading ? 'Processing...' : 'Confirm Payment'}</button>
          </div>
        </div>
      </div>
      <div className="modal-backdrop show" style={{ zIndex: 1999 }}></div>
    </div>
  )
}

export default PaymentConfirmDialog
