import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Paper,
  Typography,
  IconButton,
  TextField,
  Avatar,
  Badge,
  CircularProgress
} from '@mui/material';
import {
  Close,
  Send,
  Minimize
} from '@mui/icons-material';
import { chatService } from '../../services/chatService';

const ChatWindow = ({ 
  currentUser, 
  recipient, 
  onClose, 
  onMinimize, 
  position,
  unread = 0,
  onRead
}) => {
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);
  const subscriptionRef = useRef(null);
  const broadcastChannelRef = useRef(null);
  const typingTimeoutRef = useRef(null);
  const lastTypingSentRef = useRef(0);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    loadMessages();
    
    // Subscribe to new messages specifically for this conversation
    const channel = chatService.subscribeToMessages(currentUser.userid, (msg) => {
      if (msg.sender_id === recipient.userid) {
        setMessages(prev => [...prev, msg]);
        chatService.markAsRead([msg.id]);
        if (onRead) onRead();
        scrollToBottom();
      }
    });
    subscriptionRef.current = channel;

    // Subscribe to Typing indicators
    const typingChannel = chatService.joinConversation(currentUser.userid, recipient.userid, (payload) => {
        setIsTyping(true);
        if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
        typingTimeoutRef.current = setTimeout(() => setIsTyping(false), 3000);
    });
    broadcastChannelRef.current = typingChannel;

    return () => {
      if (subscriptionRef.current) supabase.removeChannel(subscriptionRef.current);
      if (broadcastChannelRef.current) supabase.removeChannel(broadcastChannelRef.current);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    };
  }, [recipient.userid]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const handleInputChange = (e) => {
    setNewMessage(e.target.value);
    
    const now = Date.now();
    if (now - lastTypingSentRef.current > 2000) {
        chatService.sendTyping(broadcastChannelRef.current, currentUser.userid);
        lastTypingSentRef.current = now;
    }
  };

  const loadMessages = async () => {
    setLoading(true);
    const res = await chatService.getMessages(currentUser.userid, recipient.userid);
    if (res.success) {
      setMessages(res.data);
      // Mark unread as read
      const unreadIds = res.data
        .filter(m => !m.is_read && m.receiver_id === currentUser.userid)
        .map(m => m.id);
      if (unreadIds.length > 0) {
        chatService.markAsRead(unreadIds);
        if (onRead) onRead();
      }
    }
    setLoading(false);
  };

  const handleSend = async () => {
    if (!newMessage.trim()) return;
    setSending(true);
    
    // Optimistic update
    const tempMsg = {
      id: 'temp-' + Date.now(),
      sender_id: currentUser.userid,
      receiver_id: recipient.userid,
      content: newMessage,
      created_at: new Date().toISOString(),
      is_read: false
    };
    setMessages(prev => [...prev, tempMsg]);
    setNewMessage('');
    scrollToBottom();

    const res = await chatService.sendMessage(currentUser.userid, recipient.userid, tempMsg.content);
    
    if (res.success) {
      // Replace temp message with real one
      setMessages(prev => prev.map(m => m.id === tempMsg.id ? res.data : m));
    } else {
      // Handle error (maybe show red retry icon)
      console.error("Failed to send");
    }
    setSending(false);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const triggerMinimize = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (onMinimize) onMinimize();
  };

  const triggerClose = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (onClose) onClose();
  };

  return (
    <Paper 
      elevation={3}
      sx={{
        position: 'fixed',
        bottom: 0,
        right: position * 340 + 320, // Offset from the users list
        width: 320,
        height: 400,
        display: 'flex',
        flexDirection: 'column',
        borderTopLeftRadius: 8,
        borderTopRightRadius: 8,
        overflow: 'hidden',
        zIndex: 2147483000
      }}
    >
      {/* Header */}
      <Box sx={{ 
        p: 1.5, 
        bgcolor: 'primary.main', 
        color: 'white',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        cursor: 'default'
      }}
      >
        <Box display="flex" alignItems="center" gap={1}>
          <Badge 
            variant="dot" 
            color={recipient.isOnline ? "success" : "default"}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
          >
            <Avatar sx={{ width: 30, height: 30, fontSize: '0.8rem' }}>
              {recipient.firstname?.[0]}{recipient.lastname?.[0]}
            </Avatar>
          </Badge>
          <Typography variant="subtitle2" noWrap sx={{ maxWidth: 150 }}>
            {recipient.firstname} {recipient.lastname}
          </Typography>
          {unread > 0 && (
            <Badge badgeContent={unread} color="error" sx={{ ml: 1 }} />
          )}
        </Box>
        <Box>
          <IconButton
            size="small"
            onMouseDown={triggerMinimize}
            onTouchStart={triggerMinimize}
            onClick={triggerMinimize}
            sx={{ color: 'white' }}
          >
            <Minimize fontSize="small" />
          </IconButton>
          <IconButton
            size="small"
            onMouseDown={triggerClose}
            onTouchStart={triggerClose}
            onClick={triggerClose}
            sx={{ color: 'white' }}
          >
            <Close fontSize="small" />
          </IconButton>
        </Box>
      </Box>

      {/* Messages Area */}
      <Box sx={{ 
        flex: 1, 
        overflowY: 'auto', 
        p: 2,
        bgcolor: '#f5f5f5',
        display: 'flex',
        flexDirection: 'column',
        gap: 1
      }}>
        {loading ? (
          <Box display="flex" justifyContent="center" pt={5}>
            <CircularProgress size={24} />
          </Box>
        ) : (
          messages.map((msg, index) => {
            const isMe = msg.sender_id === currentUser.userid;
            return (
              <Box 
                key={msg.id || index}
                sx={{
                  alignSelf: isMe ? 'flex-end' : 'flex-start',
                  maxWidth: '80%',
                }}
              >
                <Paper sx={{ 
                  p: 1, 
                  bgcolor: isMe ? 'primary.light' : 'white',
                  color: isMe ? 'white' : 'text.primary',
                  borderRadius: 2
                }}>
                  <Typography variant="body2">{msg.content}</Typography>
                </Paper>
                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', textAlign: isMe ? 'right' : 'left', mt: 0.5, fontSize: '0.7rem' }}>
                  {new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </Typography>
              </Box>
            );
          })
        )}
        {isTyping && (
          <Box sx={{ alignSelf: 'flex-start', mb: 1, ml: 1 }}>
             <Typography variant="caption" color="text.secondary" sx={{ fontStyle: 'italic' }}>
               Typing...
             </Typography>
          </Box>
        )}
        <div ref={messagesEndRef} />
      </Box>

      {/* Input Area */}
      <Box sx={{ p: 1.5, bgcolor: 'white', borderTop: '1px solid #eee' }}>
        <Box display="flex" gap={1}>
          <TextField
            fullWidth
            size="small"
            placeholder="Type a message..."
            value={newMessage}
            onChange={handleInputChange}
            onKeyDown={handleKeyPress}
            multiline
            maxRows={3}
            sx={{ '& .MuiOutlinedInput-root': { borderRadius: 3 } }}
          />
          <IconButton 
            color="primary" 
            onClick={handleSend}
            disabled={!newMessage.trim() || sending}
          >
            <Send />
          </IconButton>
        </Box>
      </Box>
    </Paper>
  );
};

// Need to import supabase for removeChannel
import { supabase } from '../../supabaseClient';

export default ChatWindow;
