import React, { useState } from 'react'
import { authService } from '../../authService'
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Grid,
  Typography,
  Box,
  Avatar,
  IconButton,
  Alert,
  Chip,
  CircularProgress
} from '@mui/material';
import {
  Close as CloseIcon,
  Edit as EditIcon,
  Save as SaveIcon,
  Person as PersonIcon,
  Email as EmailIcon,
  Phone as PhoneIcon,
  Badge as BadgeIcon,
  Home as HomeIcon,
  CalendarMonth as CalendarIcon,
  AccessTime as AccessTimeIcon,
  VerifiedUser as VerifiedUserIcon,
  Shield as ShieldIcon
} from '@mui/icons-material';

const ProfileModal = ({ user, isOpen, onClose, onUpdate }) => {
  const [isEditing, setIsEditing] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')
  const [formData, setFormData] = useState({
    firstname: user.firstname || '',
    lastname: user.lastname || '',
    email: user.email || '',
    phone: user.phone || '',
    address: user.address || ''
  })

  if (!isOpen) return null

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    setError('')
  }

  const handleSave = async () => {
    setLoading(true)
    setError('')
    setSuccess('')

    try {
      const result = await authService.updateProfile(user.userid, formData)
      if (result.success) {
        setSuccess('Profile updated successfully!')
        setIsEditing(false)
        // Update parent component with new user data
        onUpdate({ ...user, ...formData })
        setTimeout(() => {
          setSuccess('')
        }, 2000)
      } else {
        setError(result.error || 'Failed to update profile')
      }
    } catch (err) {
      setError('An error occurred while updating profile')
    }
    setLoading(false)
  }

  const handleCancel = () => {
    setFormData({
      firstname: user.firstname || '',
      lastname: user.lastname || '',
      email: user.email || '',
      phone: user.phone || '',
      address: user.address || ''
    })
    setIsEditing(false)
    setError('')
    setSuccess('')
  }

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A'
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })
  }

  return (
    <Dialog
      open={isOpen}
      onClose={onClose}
      maxWidth="sm"
      fullWidth
      scroll="paper"
    >
      <DialogTitle sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <PersonIcon color="primary" />
          <Typography variant="h6">My Profile</Typography>
        </Box>
        <IconButton onClick={onClose} size="small">
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent dividers>
        {/* Error/Success Messages */}
        {error && (
          <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
            {error}
          </Alert>
        )}
        {success && (
          <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess('')}>
            {success}
          </Alert>
        )}

        {/* User Avatar and Info */}
        <Box sx={{ textAlign: 'center', mb: 4 }}>
          <Avatar
            sx={{
              width: 100,
              height: 100,
              bgcolor: 'primary.main',
              fontSize: '2.5rem',
              fontWeight: 'bold',
              margin: '0 auto',
              mb: 2,
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
            }}
          >
            {user.firstname?.charAt(0)}{user.lastname?.charAt(0)}
          </Avatar>
          <Typography variant="h5" fontWeight="bold">
            {user.firstname} {user.lastname}
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1, mt: 1, color: 'text.secondary' }}>
            <ShieldIcon fontSize="small" />
            <Typography variant="subtitle2">{user.role}</Typography>
          </Box>
        </Box>

        {/* Profile Information */}
        <Box sx={{ bgcolor: 'background.default', p: 3, borderRadius: 2 }}>
          <Grid container spacing={2}>
            <Grid item xs={6}>
              <Typography variant="caption" color="text.secondary" gutterBottom>
                First Name
              </Typography>
              {isEditing ? (
                <TextField
                  fullWidth
                  size="small"
                  value={formData.firstname}
                  onChange={(e) => handleChange('firstname', e.target.value)}
                />
              ) : (
                <Typography variant="body1" fontWeight="500">
                  {user.firstname}
                </Typography>
              )}
            </Grid>

            <Grid item xs={6}>
              <Typography variant="caption" color="text.secondary" gutterBottom>
                Last Name
              </Typography>
              {isEditing ? (
                <TextField
                  fullWidth
                  size="small"
                  value={formData.lastname}
                  onChange={(e) => handleChange('lastname', e.target.value)}
                />
              ) : (
                <Typography variant="body1" fontWeight="500">
                  {user.lastname}
                </Typography>
              )}
            </Grid>

            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <EmailIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  Email Address
                </Typography>
              </Box>
              {isEditing ? (
                <TextField
                  fullWidth
                  size="small"
                  type="email"
                  value={formData.email}
                  onChange={(e) => handleChange('email', e.target.value)}
                />
              ) : (
                <Typography variant="body1" fontWeight="500">
                  {user.email}
                </Typography>
              )}
            </Grid>

            <Grid item xs={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <PhoneIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  Phone Number
                </Typography>
              </Box>
              {isEditing ? (
                <TextField
                  fullWidth
                  size="small"
                  value={formData.phone}
                  onChange={(e) => handleChange('phone', e.target.value)}
                  placeholder="Enter phone number"
                />
              ) : (
                <Typography variant="body1" fontWeight="500">
                  {user.phone || 'Not provided'}
                </Typography>
              )}
            </Grid>

            <Grid item xs={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <BadgeIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  User ID
                </Typography>
              </Box>
              <Typography variant="body1" fontWeight="500" color="primary">
                {user.userid}
              </Typography>
            </Grid>

            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <HomeIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  Address
                </Typography>
              </Box>
              {isEditing ? (
                <TextField
                  fullWidth
                  multiline
                  rows={2}
                  size="small"
                  value={formData.address}
                  onChange={(e) => handleChange('address', e.target.value)}
                  placeholder="Enter address"
                />
              ) : (
                <Typography variant="body1" fontWeight="500">
                  {user.address || 'Not provided'}
                </Typography>
              )}
            </Grid>

            <Grid item xs={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <CalendarIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  Account Created
                </Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                {formatDate(user.datecreated)}
              </Typography>
            </Grid>

            <Grid item xs={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <AccessTimeIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  Last Login
                </Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                {formatDate(user.lastlogin)}
              </Typography>
            </Grid>

            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                <VerifiedUserIcon fontSize="small" color="action" />
                <Typography variant="caption" color="text.secondary">
                  Account Status
                </Typography>
              </Box>
              <Chip
                label={user.status}
                color={user.status === 'active' ? 'success' : 'error'}
                size="small"
                variant="outlined"
              />
            </Grid>
          </Grid>
        </Box>
      </DialogContent>

      <DialogActions>
        {isEditing ? (
          <>
            <Button onClick={handleCancel} disabled={loading}>
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              variant="contained"
              disabled={loading}
              startIcon={loading ? <CircularProgress size={20} /> : <SaveIcon />}
            >
              Save Changes
            </Button>
          </>
        ) : (
          <>
            <Button onClick={onClose}>
              Close
            </Button>
            <Button
              onClick={() => setIsEditing(true)}
              variant="contained"
              startIcon={<EditIcon />}
            >
              Edit Profile
            </Button>
          </>
        )}
      </DialogActions>
    </Dialog>
  )
}

export default ProfileModal
